const raw = $json.choices?.[0]?.message?.content || '{}';
let ai;
try {
  ai = JSON.parse(raw);
} catch (e) {
  ai = { error: 'Parse error', raw };
}

const input = $items('SET - Entrada + Brand JSON')[0].json;

const compatibilidad = {
  instagram: ['post_estatico', 'carrusel', 'story', 'guion_reel'],
  linkedin:  ['post_estatico', 'carrusel'],
  ambas:     ['post_estatico', 'carrusel'],
};

const plataformaKey    = String(input.plataforma || 'Instagram').toLowerCase();
const formatoSolicitado = String(input.formato_contenido || 'post_estatico').toLowerCase();
const formatosValidos  = compatibilidad[plataformaKey] || compatibilidad.instagram;
const formatoFinal     = formatosValidos.includes(formatoSolicitado) ? formatoSolicitado : formatosValidos[0];

// react_data: usa lo que generó el LLM, con fallback por formato
let react_data = ai.react_data;
if (!react_data) {
  const fmt = formatoFinal;
  if (fmt === 'carrusel')    react_data = { slides: ai.slides || [] };
  else if (fmt === 'story')  react_data = { frames: ai.frames || [] };
  else if (fmt === 'guion_reel') react_data = { gancho: ai.hook || '', problema: ai.copy || '', puntos: ai.escenas || [], cierre: '', cta: '', duracion: '60 seg' };
  else react_data = { hook: ai.hook || '', cuerpo: ai.copy || '', cierre: ai.observaciones || '', cta: (ai.caption_instagram || '').slice(0, 120), hashtags: ai.hashtags || [], plataforma: input.plataforma };
}

const contentId = String(Date.now());

return [{
  json: {
    content_id:               contentId,
    cliente:                  'Megactivo',
    plataforma:               input.plataforma,
    formato_contenido:        formatoFinal,
    formato_solicitado:       formatoSolicitado,
    objetivo_post:            input.objetivo_post,
    fecha_publicacion:        input.fecha_publicacion,
    hora_publicacion:         input.hora_publicacion,
    calendar_provider:        input.calendar_provider,
    brand_json:               input.brand_json,
    pilar_contenido:          ai.pilar_contenido || '',
    react_data,
    caption_instagram:        ai.caption_instagram || '',
    caption_linkedin:         ai.caption_linkedin  || '',
    necesita_foto:            Boolean(ai.necesita_foto),
    prompt_imagen:            ai.prompt_imagen || '',
    hashtags:                 ai.hashtags || [],
    observaciones:            ai.observaciones || '',
    fecha_publicacion_sugerida: ai.fecha_publicacion_sugerida || input.fecha_publicacion,
    imagen_url:               '',
    estado:                   'pendiente aprobacion'
  }
}];

const aprobacionData = $items('SET - Datos aprobación')[0].json;
const driveResults = $input.all();

let imagen_url = '';

if (driveResults && driveResults.length > 0 && driveResults[0].json && driveResults[0].json.id) {
  const fileId = driveResults[0].json.id;
  imagen_url = `https://drive.google.com/thumbnail?id=${fileId}&sz=w1000`;
}

return [{
  json: {
    accion: aprobacionData.accion,
    content_id: aprobacionData.content_id,
    calendar_event_id: aprobacionData.calendar_event_id,
    calendar_provider: aprobacionData.calendar_provider,
    comentarios: aprobacionData.comentarios,
    cliente: aprobacionData.cliente,
    plataforma: aprobacionData.plataforma,
    formato_contenido: aprobacionData.formato_contenido,
    pilar_contenido: aprobacionData.pilar_contenido,
    caption_instagram: aprobacionData.caption_instagram,
    caption_linkedin: aprobacionData.caption_linkedin,
    hashtags: aprobacionData.hashtags,
    fecha_publicacion_sugerida: aprobacionData.fecha_publicacion_sugerida,
    hora_publicacion: aprobacionData.hora_publicacion,
    observaciones: aprobacionData.observaciones,
    imagen_url
  }
}];

const datos = $items('Code - process results')[0].json;
const evento = $json || {};
const eventId = evento.id || evento.Id || '';
const nota = eventId ? 'Evento creado con éxito' : 'No se pudo crear el evento de calendario';
const comentariosFinal = [datos.comentarios, nota].filter(Boolean).join(' | ');

return [{
  json: {
    ...datos,
    calendar_event_id: eventId || datos.calendar_event_id,
    comentarios: comentariosFinal
  }
}];

const response = $json;
const parts = (response.candidates && response.candidates[0] && response.candidates[0].content && response.candidates[0].content.parts) || [];
const imagePart = parts.find(p => p.inlineData || p.inline_data);
const inline = imagePart && (imagePart.inlineData || imagePart.inline_data);

if (!inline || !inline.data) {
  throw new Error('Gemini no devolvio una imagen: ' + JSON.stringify(response).slice(0, 500));
}

const mimeType = inline.mimeType || inline.mime_type || 'image/png';
const buffer = Buffer.from(inline.data, 'base64');

return [{
  json: $('CODE - Parsear respuesta + React mapping').item.json,
  binary: {
    data: await this.helpers.prepareBinaryData(buffer, 'imagen.png', mimeType)
  }
}];

const files = $input.all();
if (!files.length) {
  return [];
}
const random = files[Math.floor(Math.random() * files.length)];
return [{ json: { fileId: random.json.id } }];
